(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const slides=[...document.querySelectorAll('.slide')],dots=[...document.querySelectorAll('[data-slide]')],pause=document.querySelector('#pauseSlides');let current=0,timer=null,paused=reduced;function show(index){current=index;slides.forEach((s,i)=>s.classList.toggle('active',i===index));dots.forEach((d,i)=>{d.classList.toggle('active',i===index);d.setAttribute('aria-pressed',String(i===index))})}function restart(){clearInterval(timer);timer=null;if(!paused&&!document.hidden&&slides.length>1)timer=setInterval(()=>show((current+1)%slides.length),5500)}dots.forEach(d=>d.addEventListener('click',()=>{show(Number(d.dataset.slide));restart()}));if(pause){pause.setAttribute('aria-pressed',String(paused));pause.textContent=paused?'▶':'Ⅱ';pause.addEventListener('click',()=>{paused=!paused;pause.setAttribute('aria-pressed',String(paused));pause.textContent=paused?'▶':'Ⅱ';restart()})}document.addEventListener('visibilitychange',restart);restart();if(!reduced&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));document.documentElement.classList.add('motion-ready')}})();

(()=>{const video=document.querySelector('#homeVideo'),button=document.querySelector('#pauseHomeVideo');if(!video||!button)return;let userPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;video.muted=true;function sync(){button.textContent=video.paused?'▶':'Ⅱ';button.setAttribute('aria-pressed',String(video.paused))}function play(){video.play().catch(sync)}video.addEventListener('play',sync);video.addEventListener('pause',sync);button.addEventListener('click',()=>{userPaused=!video.paused;if(userPaused)video.pause();else play()});document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();else if(!userPaused)play()});if(userPaused)video.pause();else play();sync()})();
